def solve_quiz_game(N, K, Q, A):
    scores = [K] * N
    eliminated = set()

    for player in A:
        if player not in eliminated:
            for i in range(N):
                if i != player - 1:
                    scores[i] -= 1
                    if scores[i] <= 0:
                        eliminated.add(i + 1)

    for i in range(1, N + 1):
        print("Yes" if i not in eliminated else "No")

